const upsertCheck = `-- name: UpsertCheck :one
INSERT INTO it_assessment.checks (tenant_id, assessment_id, check_key, status, target, raw_result, duration_ms)
VALUES ($1, $2, $3, $4, $5, $6, $7)
ON CONFLICT (tenant_id, assessment_id, check_key, target) DO UPDATE SET status = EXCLUDED.status, raw_result = EXCLUDED.raw_result
RETURNING id
`

type UpsertCheckParams struct {
	TenantID     uuid.UUID
	AssessmentID uuid.UUID
	CheckKey     string
	Status       string
	Target       string
	RawResult    []byte
	DurationMs   *int32
}

func (q *Queries) UpsertCheck(ctx context.Context, arg UpsertCheckParams) (uuid.UUID, error) {
	row := q.db.QueryRow(ctx, upsertCheck,
		arg.TenantID,
		arg.AssessmentID,
		arg.CheckKey,
		arg.Status,
		arg.Target,
		arg.RawResult,
		arg.DurationMs,
	)
	var id uuid.UUID
	err := row.Scan(&id)
	return id, err
}
